export const getGetTutorAvailableSlotsUrl = (tutorId: number,
    params: GetTutorAvailableSlotsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/tutors/${tutorId}/available-slots?${stringifiedParams}` : `/api/tutors/${tutorId}/available-slots`
}

